import { Controller, Get, Post, Put, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
// 가정: 수정은 신청·반려 상태에서만 허용하고, 승인은 BUDGET_COMMITMENT_APPROVED, 승인 취소는 INVALID_STATE로 거절한다.
const EDITABLE_STATUSES = ['신청', '반려'];
// 가정: 취소는 신청·승인 상태에서만 허용한다.
const CANCELABLE_STATUSES = ['신청', '승인'];

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function toId(value: unknown, label: string, required: boolean): number | null {
  if (value === undefined || value === null || value === '') {
    if (required) {
      throw invalid(label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  const n = typeof value === 'number' ? value : typeof value === 'string' && /^[0-9]+$/.test(value.trim()) ? Number(value.trim()) : NaN;
  if (!Number.isInteger(n) || n <= 0) {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return n;
}

function toAmount(value: unknown): number {
  if (value === undefined || value === null || value === '') {
    throw invalid('원인행위 금액을 입력해 주세요.');
  }
  const n = typeof value === 'number' ? value : typeof value === 'string' && /^-?[0-9]+(\.[0-9]+)?$/.test(value.trim()) ? Number(value.trim()) : NaN;
  if (!Number.isFinite(n) || n <= 0) {
    throw invalid('원인행위 금액은 0보다 큰 숫자여야 합니다.');
  }
  return n;
}

function toName(value: unknown): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw invalid('원인행위 명칭을 입력해 주세요.');
  }
  if (value.trim().length > 200) {
    throw invalid('원인행위 명칭은 200자 이하여야 합니다.');
  }
  return value.trim();
}

function pathId(value: string | undefined): number {
  const n = toId(value, '원인행위 ID', true);
  return n as number;
}

type Db = { query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>; execute: (sql: string, params?: Record<string, unknown>) => Promise<number> };

async function checkRefs(db: Db, projectId: number, budgetAccountId: number, partnerId: number | null): Promise<void> {
  const projects = await db.query('SELECT project_id FROM project WHERE project_id = CAST(:id AS bigint)', { id: projectId });
  if (projects.length === 0) {
    throw invalid('존재하지 않는 프로젝트입니다.');
  }
  const accounts = await db.query('SELECT budget_account_id FROM budget_account WHERE budget_account_id = CAST(:id AS bigint)', { id: budgetAccountId });
  if (accounts.length === 0) {
    throw invalid('존재하지 않는 예산과목입니다.');
  }
  if (partnerId !== null) {
    const partners = await db.query('SELECT partner_id FROM partner WHERE partner_id = CAST(:id AS bigint)', { id: partnerId });
    if (partners.length === 0) {
      throw invalid('존재하지 않는 거래처입니다.');
    }
  }
}

@Controller('api/v1')
export class FnSfr00404Controller {
  @Post('/budget-commitments')
  @HttpCode(200)
  async createBudgetCommitment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const name = toName(data['name']);
    const projectId = toId(data['projectId'], '프로젝트', true) as number;
    const budgetAccountId = toId(data['budgetAccountId'], '예산과목', true) as number;
    const partnerId = toId(data['partnerId'], '거래처', false);
    const amount = toAmount(data['amount']);
    return transaction(async (db) => {
      await checkRefs(db, projectId, budgetAccountId, partnerId);
      const rows = await db.query(
        'INSERT INTO budget_commitment (name, project_id, budget_account_id, partner_id, amount, approval_status, created_at, updated_at) ' +
          'VALUES (:name, CAST(:projectId AS bigint), CAST(:budgetAccountId AS bigint), CAST(:partnerId AS bigint), CAST(:amount AS numeric), :status, now(), now()) ' +
          'RETURNING budget_commitment_id AS "budgetCommitmentId", approval_status AS "approvalStatus"',
        { name, projectId, budgetAccountId, partnerId, amount, status: '신청' },
      );
      return rows[0];
    });
  }

  @Get('/budget-commitments')
  async listBudgetCommitments(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const projectId = toId(query['projectId'], '프로젝트', false);
    const budgetAccountId = toId(query['budgetAccountId'], '예산과목', false);
    const pageRaw = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const sizeRaw = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(pageRaw) || pageRaw < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
      throw invalid('page 또는 size 형식이 올바르지 않습니다.');
    }
    const page = pageRaw;
    const size = Math.min(sizeRaw, MAX_SIZE);
    return transaction(async (db) => {
      const where =
        'WHERE (CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint)) ' +
        'AND (CAST(:budgetAccountId AS bigint) IS NULL OR budget_account_id = CAST(:budgetAccountId AS bigint)) ';
      const counts = await db.query('SELECT COUNT(*) AS "total" FROM budget_commitment ' + where, { projectId, budgetAccountId });
      const items = await db.query(
        'SELECT budget_commitment_id AS "budgetCommitmentId", name AS "name", project_id AS "projectId", ' +
          'budget_account_id AS "budgetAccountId", partner_id AS "partnerId", amount AS "amount", approval_status AS "approvalStatus" ' +
          'FROM budget_commitment ' +
          where +
          'ORDER BY budget_commitment_id DESC LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)',
        { projectId, budgetAccountId, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Put('/budget-commitments/:budgetCommitmentId')
  async updateBudgetCommitment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = pathId(req.params['budgetCommitmentId']);
    const data = checks.inputOf(req.body);
    const name = toName(data['name']);
    const projectId = toId(data['projectId'], '프로젝트', true) as number;
    const budgetAccountId = toId(data['budgetAccountId'], '예산과목', true) as number;
    const partnerId = toId(data['partnerId'], '거래처', false);
    const amount = toAmount(data['amount']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM budget_commitment WHERE budget_commitment_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'BUDGET_COMMITMENT_NOT_FOUND', '원인행위를 찾을 수 없습니다.');
      }
      const status = found[0].approvalStatus as string;
      if (status === '승인') {
        throw new ApiError(409, 'BUDGET_COMMITMENT_APPROVED', '승인된 원인행위는 임의로 수정할 수 없습니다. 승인 취소 절차를 거쳐 주세요.');
      }
      if (!EDITABLE_STATUSES.includes(status)) {
        throw new ApiError(409, 'INVALID_STATE', '현재 상태에서는 수정할 수 없습니다.');
      }
      await checkRefs(db, projectId, budgetAccountId, partnerId);
      const rows = await db.query(
        'UPDATE budget_commitment SET name = :name, project_id = CAST(:projectId AS bigint), budget_account_id = CAST(:budgetAccountId AS bigint), ' +
          'partner_id = CAST(:partnerId AS bigint), amount = CAST(:amount AS numeric), updated_at = now() ' +
          'WHERE budget_commitment_id = CAST(:id AS bigint) RETURNING budget_commitment_id AS "budgetCommitmentId"',
        { id, name, projectId, budgetAccountId, partnerId, amount },
      );
      return rows[0];
    });
  }

  @Post('/budget-commitments/:budgetCommitmentId/cancel')
  @HttpCode(200)
  async cancelBudgetCommitment(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = pathId(req.params['budgetCommitmentId']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_status AS "approvalStatus" FROM budget_commitment WHERE budget_commitment_id = CAST(:id AS bigint) FOR UPDATE',
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'BUDGET_COMMITMENT_NOT_FOUND', '원인행위를 찾을 수 없습니다.');
      }
      if (!CANCELABLE_STATUSES.includes(found[0].approvalStatus as string)) {
        throw new ApiError(409, 'BUDGET_COMMITMENT_NOT_CANCELABLE', '취소할 수 없는 상태입니다.');
      }
      const rows = await db.query(
        'UPDATE budget_commitment SET approval_status = :status, updated_at = now() ' +
          'WHERE budget_commitment_id = CAST(:id AS bigint) RETURNING approval_status AS "approvalStatus"',
        { id, status: '승인 취소' },
      );
      return rows[0];
    });
  }
}

