import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  NumberInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

function CommitmentForm({ role, initial, id, onDone }: { role: string; initial: Row; id?: unknown; onDone: () => void }) {
  const [name, setName] = useState<unknown>(initial['name'] ?? '');
  const [projectId, setProjectId] = useState<unknown>(initial['projectId'] ?? '');
  const [budgetAccountId, setBudgetAccountId] = useState<unknown>(initial['budgetAccountId'] ?? '');
  const [partnerId, setPartnerId] = useState<unknown>(initial['partnerId'] ?? '');
  const [amount, setAmount] = useState<unknown>(initial['amount'] ?? '');

  async function submit() {
    if (String(name).trim() === '') {
      throw new Error('원인행위 명칭을 입력해 주세요.');
    }
    if (projectId === '' || projectId === null) {
      throw new Error('프로젝트를 선택해 주세요.');
    }
    if (budgetAccountId === '' || budgetAccountId === null) {
      throw new Error('예산과목을 선택해 주세요.');
    }
    if (amount === '' || amount === null) {
      throw new Error('원인행위 금액을 입력해 주세요.');
    }
    const body: Row = { name, projectId, budgetAccountId, amount };
    if (partnerId !== '' && partnerId !== null) {
      body['partnerId'] = partnerId;
    }
    if (id === undefined) {
      await call('POST', '/budget-commitments', role, body);
    } else {
      await call('PUT', '/budget-commitments/' + String(id), role, body);
    }
    onDone();
  }

  return (
    <Form onSubmit={submit} submit={id === undefined ? '등록' : '수정'}>
      <Field label='원인행위 명칭' required wide>
        <TextInput value={name} onChange={setName} />
      </Field>
      <Field label='프로젝트' required>
        <LookupSelect table='project' role={role} value={projectId} onChange={setProjectId} />
      </Field>
      <Field label='예산과목' required>
        <LookupSelect table='budget_account' role={role} value={budgetAccountId} onChange={setBudgetAccountId} />
      </Field>
      <Field label='거래처'>
        <LookupSelect table='partner' role={role} value={partnerId} onChange={setPartnerId} placeholder='선택 안 함' />
      </Field>
      <Field label='원인행위 금액' required>
        <NumberInput value={amount} onChange={setAmount} />
      </Field>
    </Form>
  );
}

export default function FnSfr00404Page({ role, notify }: PageProps) {
  const [projectDraft, setProjectDraft] = useState<unknown>('');
  const [accountDraft, setAccountDraft] = useState<unknown>('');
  const [applied, setApplied] = useState<{ projectId: unknown; budgetAccountId: unknown }>({ projectId: '', budgetAccountId: '' });
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [drawer, setDrawer] = useState<'create' | 'edit' | 'cancel' | null>(null);

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/budget-commitments', role, undefined, {
        projectId: applied.projectId,
        budgetAccountId: applied.budgetAccountId,
        page,
        size: SIZE,
      }),
    [role, applied.projectId, applied.budgetAccountId, page],
  );

  function search() {
    setPage(0);
    setApplied({ projectId: projectDraft, budgetAccountId: accountDraft });
  }

  function reset() {
    setProjectDraft('');
    setAccountDraft('');
    setPage(0);
    setApplied({ projectId: '', budgetAccountId: '' });
  }

  function finish(message: string) {
    notify(message);
    setDrawer(null);
    setSelected(null);
    list.reload();
  }

  const status = selected ? String(selected['approvalStatus']) : '';
  const canEdit = status === '신청' || status === '반려';
  const canCancel = status === '신청' || status === '승인';

  const drawerView = (
    <>
      {drawer === 'create' && (
        <Drawer title='원인행위 등록' onClose={() => setDrawer(null)}>
          <CommitmentForm role={role} initial={{}} onDone={() => finish('원인행위를 등록했습니다.')} />
        </Drawer>
      )}
      {drawer === 'edit' && selected && (
        <Drawer title='원인행위 수정' onClose={() => setDrawer(null)}>
          <CommitmentForm
            role={role}
            initial={selected}
            id={selected['budgetCommitmentId']}
            onDone={() => finish('원인행위를 수정했습니다.')}
          />
        </Drawer>
      )}
      {drawer === 'cancel' && selected && (
        <Drawer title='원인행위 취소' onClose={() => setDrawer(null)}>
          <Form
            submit='취소 처리'
            danger
            note='취소하면 승인 상태가 승인 취소로 바뀌고 되돌릴 수 없습니다.'
            onSubmit={async () => {
              await call('POST', '/budget-commitments/' + String(selected['budgetCommitmentId']) + '/cancel', role, {});
              finish('원인행위를 취소했습니다.');
            }}
          >
            <p>{String(selected['name'])} 원인행위를 취소합니다.</p>
          </Form>
        </Drawer>
      )}
    </>
  );

  if (selected) {
    return (
      <div className='doc'>
        <button className='ghost' onClick={() => setSelected(null)}>
          목록으로
        </button>
        <section className='box'>
          <h2>원인행위</h2>
          <Pairs
            items={[
              ['원인행위 명칭', String(selected['name'])],
              ['프로젝트', <RefName table='project' role={role} value={selected['projectId']} />],
              ['예산과목', <RefName table='budget_account' role={role} value={selected['budgetAccountId']} />],
              ['거래처', selected['partnerId'] ? <RefName table='partner' role={role} value={selected['partnerId']} /> : '-'],
              ['원인행위 금액', <Num value={selected['amount']} />],
              ['승인 상태', <Badge value={selected['approvalStatus']} />],
            ]}
          />
        </section>
        <section className='box'>
          <h2>처리</h2>
          {canEdit && <button onClick={() => setDrawer('edit')}>수정</button>}
          {canCancel && (
            <button className='ghost' onClick={() => setDrawer('cancel')}>
              취소
            </button>
          )}
          {!canEdit && !canCancel && <p>이 상태에서는 처리할 수 있는 작업이 없습니다.</p>}
        </section>
        {drawerView}
      </div>
    );
  }

  const data = list.data;
  return (
    <div className='doc'>
      <section className='box'>
        <h2>원인행위 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label='프로젝트'>
            <LookupSelect table='project' role={role} value={projectDraft} onChange={setProjectDraft} placeholder='전체' />
          </Field>
          <Field label='예산과목'>
            <LookupSelect table='budget_account' role={role} value={accountDraft} onChange={setAccountDraft} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button onClick={() => setDrawer('create')}>원인행위 등록</button>
        </Band>
        {list.error && <ErrorText text={list.error} />}
        <DataTable
          columns={[
            { key: 'name', label: '원인행위 명칭' },
            { key: 'projectId', label: '프로젝트', render: (r) => <RefName table='project' role={role} value={r['projectId']} /> },
            { key: 'budgetAccountId', label: '예산과목', render: (r) => <RefName table='budget_account' role={role} value={r['budgetAccountId']} /> },
            { key: 'amount', label: '원인행위 금액', render: (r) => <Num value={r['amount']} /> },
            { key: 'approvalStatus', label: '승인 상태', render: (r) => <Badge value={r['approvalStatus']} /> },
          ]}
          rows={data?.items ?? []}
          onRowClick={(r) => setSelected(r)}
          empty='아직 등록한 원인행위가 없습니다. 원인행위 등록 버튼으로 시작해 주세요.'
        />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {drawerView}
    </div>
  );
}
